function drawMap(){let ctx=$('#minimap').getContext('2d');ctx.clearRect(0,0,220,160);let minX=Infinity,minZ=Infinity,maxX=-Infinity,maxZ=-Infinity;for(let a of samples){minX=Math.min(minX,a.p.x);maxX=Math.max(maxX,a.p.x);minZ=Math.min(minZ,a.p.z);maxZ=Math.max(maxZ,a.p.z)}let scale=Math.min(184/(maxX-minX),124/(maxZ-minZ));const xy=p=>[18+(p.x-minX)*scale,18+(p.z-minZ)*scale];ctx.beginPath();samples.forEach((a,i)=>{let p=xy(a.p);i?ctx.lineTo(...p):ctx.moveTo(...p)});ctx.strokeStyle='#111a12b0';ctx.lineWidth=8;ctx.stroke();ctx.strokeStyle='#c4cdb7';ctx.lineWidth=2;ctx.stroke();for(let z of tracks[trackIndex].aeroZones){ctx.beginPath();for(let i=0;i<=30;i++){let p=xy(trackAt((z.start+(z.end-z.start)*i/30)*length).p);i?ctx.lineTo(...p):ctx.moveTo(...p)}ctx.strokeStyle='#d5ff43';ctx.lineWidth=4;ctx.stroke();}if(mode==='race'||mode==='sprint')for(let b of bots){let p=xy(trackAt(b.s).p);ctx.beginPath();ctx.arc(...p,2.6,0,Math.PI*2);ctx.fillStyle='#f6f2e6';ctx.fill()}let p=xy(trackAt(car.s).p);ctx.beginPath();ctx.arc(...p,4.5,0,Math.PI*2);ctx.fillStyle='#d5ff43';ctx.fill();}
