function resetPose(){let a=trackAt(car.s);car.wx=a.p.x;car.wz=a.p.z;car.heading=Math.atan2(a.t.x,a.t.z);car.u=0;car.v=0;car.lateral=0;car.yaw=0;car.x=0;car.lapProgress=0;}
function projectCar(previousS){
 const count=samples.length-1;let seed=Math.floor(previousS/length*count),best=Infinity,result=null;
 for(let j=-16;j<=16;j++){let i=(seed+j+count)%count,a=samples[i].p,b=samples[i+1].p,dx=b.x-a.x,dz=b.z-a.z,q=clamp(((car.wx-a.x)*dx+(car.wz-a.z)*dz)/(dx*dx+dz*dz),0,1),px=a.x+dx*q,pz=a.z+dz*q,d=(car.wx-px)**2+(car.wz-pz)**2;if(d<best){best=d;let l=Math.hypot(dx,dz);result={s:(i+q)/count*length,x:(car.wx-px)*dz/l-(car.wz-pz)*dx/l,nx:dz/l,nz:-dx/l,px,pz};}}
 car.s=result.s%length;car.x=result.x;let delta=car.s-previousS;if(delta>length/2)delta-=length;if(delta<-length/2)delta+=length;car.total+=delta;car.lapProgress=Math.max(0,car.lapProgress+delta);
 if(Math.abs(car.x)>roadWidth/2+1)car.invalid=true;
 if(Math.abs(car.x)>16.5){let sign=Math.sign(car.x),penetration=Math.abs(car.x)-16.5;car.wx-=result.nx*penetration*sign;car.wz-=result.nz*penetration*sign;let normalSpeed=(Math.sin(car.heading)*car.u+Math.cos(car.heading)*car.lateral)*result.nx+(Math.cos(car.heading)*car.u-Math.sin(car.heading)*car.lateral)*result.nz;
 if(normalSpeed*sign>0){let vx=Math.sin(car.heading)*car.u+Math.cos(car.heading)*car.lateral-normalSpeed*result.nx*1.15,vz=Math.cos(car.heading)*car.u-Math.sin(car.heading)*car.lateral-normalSpeed*result.nz*1.15;car.u=vx*Math.sin(car.heading)+vz*Math.cos(car.heading);car.lateral=vx*Math.cos(car.heading)-vz*Math.sin(car.heading);car.yaw*=.6;if(settings.assist!=='casual'){car.parts.frontWing=clamp(car.parts.frontWing+Math.max(0,Math.abs(normalSpeed)-2)*1.2,0,100);car.parts.suspension=clamp(car.parts.suspension+Math.max(0,Math.abs(normalSpeed)-6)*.4,0,100);car.parts.floor=clamp(car.parts.floor+Math.abs(normalSpeed)*.2,0,100);}}car.x=16.5*sign;car.invalid=true;}
 let sector=Math.floor(car.s/length*3);if(sector>car.sector){car.sectorTimes.push(car.lapTime-car.sectorTimes.reduce((a,b)=>a+b,0));car.sector=sector;}
 if(previousS>length*.85&&car.s<length*.15&&delta>0&&car.lapProgress>length*.9){let time=car.lapTime,valid=!car.invalid;car.sectorTimes.push(time-car.sectorTimes.reduce((a,b)=>a+b,0));lastSectors=[...car.sectorTimes];car.sectorTimes=[];car.sector=0;car.lap++;car.lapTime=0;car.lapProgress=0;if(valid)car.best=Math.min(car.best,time);car.invalid=false;return{lap:true,time,valid};}return null;
}
