$('#engineering').onclick=()=>{showModal('SETUP WITH CONSEQUENCES.','RACE ENGINEERING / AL-02',selectSetting('eng-compound','Tyre compound',[['soft','Soft · peak grip'],['medium','Medium · balanced'],['hard','Hard · durability'],['inter','Intermediate · damp'],['wet','Wet · rain']],settings.compound)+rangeSetting('eng-engine','Engine braking / coast recovery',settings.engineBraking,0,1,.1)+rangeSetting('eng-fuel','Starting fuel · kg',settings.startFuel,5,100,1)+rangeSetting('eng-bias','Brake bias · front fraction',settings.brakeBias,.48,.66,.01)+rangeSetting('eng-pressure','Tyre pressure · psi',settings.pressure,18,28,.5)+rangeSetting('eng-ride','Ride height · metres',settings.rideHeight,.035,.12,.005)+`<p class="info">Engine braking controls off-throttle drag and 12–30 kW coast recovery; heavier pedal braking can recover up to 110 kW. Recovery is limited by rear grip, speed and battery headroom. Fuel changes mass. Compound, pressure and temperature alter tyre grip. Brake bias distributes wheel braking. Ride height changes floor efficiency. Aero balance is set in the garage.<br><br>Changes apply from your next session. In-race service: stop within 120 m after the start line and press P. Service takes 12 seconds while rivals continue.</p>`);for(let [id,key]of [['engine','engineBraking'],['compound','compound'],['fuel','startFuel'],['bias','brakeBias'],['pressure','pressure'],['ride','rideHeight']])$('#eng-'+id).onchange=e=>{settings[key]=id==='compound'?e.target.value:Number(e.target.value);saveSettings();};};
function showTelemetry(){if(state==='race'||state==='countdown'){pausedFrom=state;state='paused'}showModal('UNDERSTAND YOUR LAP.','TELEMETRY / LAST 30 MINUTES',`<canvas id="telemetry-chart" width="640" height="180"></canvas><p class="info">Speed (lime) · throttle (white) · brake (orange). ${telemetry.length} samples at 10 Hz.<br>Latest sectors: ${lastSectors.length?lastSectors.map(formatTime).join(' / '):'Complete a lap to record sectors.'}</p><table class="telemetry-table"><tr><th>Tyre</th><th>Temp</th><th>Load</th><th>Brake</th><th>Wear</th></tr>${car.wheels.map((w,i)=>`<tr><td>${['FL','FR','RL','RR'][i]}</td><td>${w.temp.toFixed(0)} °C</td><td>${w.load.toFixed(0)} N</td><td>${w.brakeTemp.toFixed(0)} °C</td><td>${w.wear.toFixed(1)}%</td></tr>`).join('')}</table><div class="modal-actions"><button class="secondary" id="csv">DOWNLOAD CSV</button></div>`);let ctx=$('#telemetry-chart').getContext('2d');for(let [index,color,scale] of [[2,'#d5ff43',360],[6,'#f5f5e8',1],[7,'#ff7457',1]]){ctx.beginPath();telemetry.forEach((r,i)=>{let x=i/Math.max(1,telemetry.length-1)*640,y=175-r[index]/scale*165;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.strokeStyle=color;ctx.lineWidth=1.5;ctx.stroke();}$('#csv').onclick=()=>{let text='time_s,distance_m,speed_kmh,rpm,gear,steer_rad,throttle,brake,ers_percent,deploy_kw,aero_open,downforce_n,fuel_kg,fl_temp_c,fr_temp_c,rl_temp_c,rr_temp_c\n'+telemetry.map(r=>r.join(',')).join('\n');downloadBlob(text,'apex-telemetry.csv','text/csv');};}
