$('#import-save').onclick=()=>$('#save-file').click();$('#save-file').onchange=async e=>{try{let f=e.target.files[0];if(!f||f.size>500000)throw Error();let d=JSON.parse(await f.text());if(d.version!==3||!d.settings||!d.bindings||!d.records)throw Error();d.bindings={...defaultBindings,...d.bindings};for(let k in defaultBindings)if(!Array.isArray(d.bindings[k])||d.bindings[k].length>3||d.bindings[k].some(v=>typeof v!=='string'||!/^([A-Za-z0-9]+)$/.test(v)))throw Error();for(let [k,v]of Object.entries(d.settings)){if(!(k in defaults)||typeof v!==typeof defaults[k])throw Error();if(typeof v==='number'&&(!Number.isFinite(v)||Math.abs(v)>100))throw Error();}const enums={device:['keyboard','gamepad','touch','tilt'],quality:['low','medium','high','ultra'],assist:['casual','simulation','hardcore'],compound:['soft','medium','hard','inter','wet'],ersMode:['manual','off','harvest','balanced','attack'],steering:['buttons','wheel','slider'],transmission:['auto','manual'],display:['windowed','fullscreen','immersive','cinematic'],profile:['Default','Two-thumb','Left-hand dominant','Right-hand dominant','Sim','Custom 1','Custom 2']};for(let[k,values]of Object.entries(enums))if(k in d.settings&&!values.includes(d.settings[k]))throw Error();if(d.settings.color&&!/^#[a-f0-9]{6}$/i.test(d.settings.color))throw Error();const ranges={engineBraking:[0,1],setup:[0,1],startFuel:[5,100],brakeBias:[.48,.66],pressure:[18,28],rideHeight:[.035,.12],volume:[0,.5],sensitivity:[.4,1.5],deadzone:[0,.4],tiltSensitivity:[.3,2],tiltDeadzone:[0,12]};for(let[k,[lo,hi]]of Object.entries(ranges))if(k in d.settings&&(d.settings[k]<lo||d.settings[k]>hi))throw Error();for(let [k,v]of Object.entries(d.records))if(typeof v!=='number'||!Number.isFinite(v)||v<=0||k.length>150)throw Error();for(let [k,v]of Object.entries(d.layouts||{}))if(!k.startsWith('apex.layout.')||!validateLayout(v)||Object.keys(v).some(x=>!labels[x]))throw Error();settings={...defaults,...d.settings};bindings=d.bindings;records=d.records;store.set('settings',settings);store.set('bindings',bindings);store.set('records.v3',records);for(let[k,v]of Object.entries(d.layouts||{}))localStorage.setItem(k,JSON.stringify(v));applySettings();toast('Save imported. Start a new session.');}catch{toast('Invalid save; import rejected.')}};

